Reference implementation (Python 3.12+):
```python
def bubble_sort(values):
    a = list(values)
    for end in range(len(a) - 1, 0, -1):
        changed = False
        for i in range(end):
            if a[i] > a[i + 1]: a[i], a[i + 1] = a[i + 1], a[i]; changed = True
        if not changed: break
    return a

def selection_sort(values):
    a = list(values)
    for i in range(len(a)):
        smallest = min(range(i, len(a)), key=a.__getitem__)
        a[i], a[smallest] = a[smallest], a[i]
    return a

def insertion_sort(values):
    a = list(values)
    for i in range(1, len(a)):
        item, j = a[i], i - 1
        while j >= 0 and a[j] > item:
            a[j + 1] = a[j]; j -= 1
        a[j + 1] = item
    return a

assert bubble_sort([3, 1, 2]) == selection_sort([3, 1, 2]) == insertion_sort([3, 1, 2]) == [1, 2, 3]
